import sys,re
f=sys.argv[1]
s=open(f,encoding="utf-8").read()
def sub(old,new,count=1):
    global s
    n=s.count(old)
    if n!=count: raise SystemExit(f"expected {count} of {old[:90]!r}, found {n}")
    s=s.replace(old,new)
def rsub(pat,new,count=1,flags=re.S):
    global s
    found=re.findall(pat,s,flags)
    if len(found)!=count: raise SystemExit(f"expected {count} of /{pat[:90]}/, found {len(found)}")
    s=re.sub(pat,lambda m:new,s,flags=flags)
